def group_updates(updates):
    updates_dict = {}
    for key, value in updates:
        if key in updates_dict:
            updates_dict[key].append(value)
        else:
            updates_dict[key] = [value]
    return sorted(updates_dict.items())

def merge_config(base, patch):
    if isinstance(base, dict) and isinstance(patch, dict):
        merged = {}
        for key in base:
            if key in patch:
                merged[key] = merge_config(base[key], patch[key])
            else:
                merged[key] = base[key]
        for key in patch:
            if key not in base:
                merged[key] = patch[key]
        return merged
    elif isinstance(base, list) and isinstance(patch, list):
        return base + patch
    elif patch is None:
        return base
    else:
        return patch

def page_bounds(page, size, total):
    if page <= 0 or size <= 0 or total < 0:
        raise ValueError("Invalid page, size, or total")
    start = max(0, min(page * size, total))
    stop = max(start, min(start + size, total))
    return start, stop

import collections

def summarize_jobs(jobs):
    summary = collections.defaultdict(lambda: (0, 0))
    for job in jobs:
        summary[job.status] = (summary[job.status][0] + job.size, summary[job.status][1] + job.size)
    return {status: (count, total_size) for status, (count, total_size) in summary.items() if total_size != 0}

import time
from typing import Callable, Optional

def retry_read(read: Callable[[], Optional[str]], attempts: int) -> Optional[str]:
    if attempts < 1:
        raise ValueError("attempts must be at least one")

    for _ in range(attempts):
        try:
            return read()
        except TimeoutError:
            continue
    return None

def iter_unique_events(events):
    seen_ids = set()
    for event in events:
        if event.get('id') is not None:
            seen_ids.add(event['id'])
        yield event

import csv

def render_row(fields, record, missing="-"):
    def escape(s):
        return s.replace("\\", "\\\\").replace("\t", "\\t").replace("\n", "\\n")

    def render_field(field, record):
        if field not in record:
            return missing
        value = record[field]
        if value is None:
            return missing
        if not value:
            return str(value)
        return escape(str(value))

    return "\t".join(render_field(field, record) for field in fields)
